    """Extend isolated marker pixels only when connected in line to a marker."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = next(value for value in counts if value != background)
    out = [row[:] for row in grid]

    # Horizontal: fill marker gaps of any length between consecutive marks.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    # Vertical: fill only intervals where the marked run is supported by
    # a horizontal line at one of the endpoint rows; this avoids free-standing
    # decorative columns from being connected.
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            supported = (sum(1 for x in grid[a] if x == marker) >= 2 or
                         sum(1 for x in grid[b] if x == marker) >= 2)
            if supported:
