 "content": "def transform(grid):
    """Fill single-cell breaks in row/column lines of foreground marks."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(value for value in counts if value != bg)
    out = [row[:] for row in grid]
    for r in range(h):
        points = [c for c in range(w) if grid[r][c] == fg]
        for a, b in zip(points, points[1:]):
            if b - a == 2 and grid[r][a+1] == bg:
                out[r][a+1] = 2
    for c in range(w):
        points = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(points, points[1:]):
            if b - a == 2 and grid[a+1][c] == bg:
                out[a+1][c] = 2
    return out

if __name__ == '__main__':
    test = [[8,8,1,1,1,1,1,1,8],[8,8,1,8,1,8,8,8,8],[8,8,8,8,1,8,8,8,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,8,8,8,1,8],[8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8]]
    for row in transform(test):
        print(row)
