 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    background = max(freq, key=freq.get)
    marker = next(value for value in freq if value != background)
    out = [row[:] for row in grid]
    # In each vertical marker track, bridge every gap between successive markers.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    # Horizontally, repair gaps where a marker is missing between two markers,
    # but retain broader disconnected horizontal intervals.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
            if b - a == 2 and grid[r][a+1] == background:
                out[r][a+1] = 2
    return out

