        positions = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            supported = ((a > 0 and grid[r][a - 1] == marker) or
                         (b + 1 < w and grid[r][b + 1] == marker))
            if supported:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            supported = ((a > 0 and grid[a - 1][c] == marker) or
                         (b + 1 < h and grid[b + 1][c] == marker))
            if supported:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out

